insert into archive.event_delivery_log_archive (
    tenant_id, outbox_event_id, outbox_event_created_at, event_type, event_key, target_topic, target_worker_id,
    delivery_status, delivery_attempt, delivery_summary, error_message, error_key,
    error_args, trace_id
)
select
    #{tenantId}, #{outboxEventId}, #{outboxEventCreatedAt}, #{eventType}, #{eventKey}, #{targetTopic},
    #{targetWorkerId}, #{deliveryStatus}, #{deliveryAttempt},
    #{deliverySummary,jdbcType=VARCHAR}::jsonb, #{errorMessage}, #{errorKey},
    #{errorArgs,jdbcType=VARCHAR}::jsonb, #{traceId}
from archive.outbox_event_archive parent
where parent.tenant_id = #{tenantId}
  and parent.id = #{outboxEventId}
  and parent.created_at = #{outboxEventCreatedAt}

